<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#25272b}h1{color:#f37021;font-size:24px;margin-bottom:3px}h2{font-size:15px;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin-top:18px}th{background:#25272b;color:white;text-align:left}td,th{padding:7px;border-bottom:1px solid #ddd}.muted{color:#777}.summary{background:#fff0e5;padding:13px;margin:14px 0}.summary span{display:inline-block;margin-right:22px}.foot{margin-top:16px}</style></head><body><h1>MentoClock</h1><h2>{{$report['business']}} · Attendance & paid leave report</h2><p>{{$report['start']}} to {{$report['end']}} · {{ucfirst($report['period'])}} · {{$report['timezone']}}</p><div class="summary"><span><strong>Gross:</strong> {{number_format($report['total_gross_hours'],2)}}h</span><span><strong>Unpaid breaks:</strong> −{{number_format($report['total_break_hours'],2)}}h</span><span><strong>Net worked:</strong> {{number_format($report['total_net_hours'],2)}}h</span><span><strong>Approved annual leave:</strong> {{number_format($report['total_annual_leave_days'],2)}} days · {{number_format($report['total_annual_leave_hours'],2)}}h{{!$report['holiday_hours_complete']?' · INCOMPLETE: configure employee paid hours':''}}</span></div><h2>Employee payroll reference summary</h2><table><thead><tr><th>Employee</th><th>Gross</th><th>Breaks</th><th>Net</th><th>Leave days</th><th>Paid leave</th><th>Reference</th><th>Finalized</th><th>Review</th></tr></thead><tbody>@foreach($report['employee_summaries'] as $s)<tr><td>{{$s['employee']}}</td><td>{{number_format($s['gross_hours'],2)}}h</td><td>{{number_format($s['break_hours'],2)}}h</td><td>{{number_format($s['net_hours'],2)}}h</td><td>{{number_format($s['annual_leave_days'],2)}}</td><td>{{$s['annual_leave_hours']===null?'Not configured':number_format($s['annual_leave_hours'],2).'h'}}</td><td>{{$s['payroll_reference_hours']===null?'Incomplete':number_format($s['payroll_reference_hours'],2).'h'}}</td><td>{{$s['finalized_records']}}</td><td>{{$s['open_records']}}</td></tr>@endforeach</tbody></table><h2>Clock records</h2><table><thead><tr><th>Employee</th><th>Workplace</th><th>Clock in</th><th>Clock out</th><th>Gross</th><th>Break</th><th>Net</th><th>Report</th><th>Review</th></tr></thead><tbody>@foreach($report['records'] as $r)<tr><td>{{$r['employee']}}</td><td>{{$r['branch']}}</td><td>{{Carbon\Carbon::parse($r['clock_in'])->format('d M Y H:i')}}</td><td>{{$r['clock_out']?Carbon\Carbon::parse($r['clock_out'])->format('d M Y H:i'):'Active'}}</td><td>{{number_format($r['gross_hours'],2)}}h</td><td>−{{number_format($r['break_hours'],2)}}h</td><td>{{number_format($r['net_hours'],2)}}h</td><td>{{number_format($r['hours'],2)}}h</td><td>{{$r['finalized_at']?'Finalized':($r['clock_out']?'Needs review':'In progress')}}</td></tr>@endforeach</tbody></table><p class="muted foot">Paid holiday hours are approved annual leave working days multiplied by the employee’s configured paid hours per leave day. Configure missing employee values before relying on the combined reference-hours total. Finalized counts mark records reviewed by a manager; corrections clear finalization and must be reviewed again. This report supports payroll preparation; it does not calculate wages. Unpaid breaks are estimates from rota minutes, not verified break punches.</p><p class="muted">Generated {{now()->tz($report['timezone'])->format('d M Y H:i')}}.</p></body></html>
